mapper.select:
SELECT *
FROM merchant
WHERE 1 = 1

    AND merchant_name LIKE CONCAT('%', #{merchantName}, '%')


    AND id IN (SELECT merchant_id FROM merchant_audit WHERE audit_status = #{auditStatus})


    AND id IN (SELECT merchant_id FROM merchant_audit WHERE audit_comment LIKE CONCAT('%', #{auditComment}, '%'))


    AND create_time <= #{createTimeEnd}


    AND create_time >= #{createTimeStart}


    AND update_time <= #{updateTimeEnd}


    AND update_time >= #{updateTimeStart}

ORDER BY update_time DESC
